--- /dev/null
+++ b/drivers/perf/ti_k3_ddr_perf.c
@@ -0,0 +1,532 @@
+// SPDX-License-Identifier: GPL-2.0-only
+/*
+ * TI DDR pmu driver
+ *
+ * Copyright (C) 2026 Texas Instruments Incorporated - https://www.ti.com/
+ */
+
+#include <linux/cpuhotplug.h>
+#include <linux/device.h>
+#include <linux/hrtimer.h>
+#include <linux/io.h>
+#include <linux/mfd/ti-ddrss.h>
+#include <linux/module.h>
+#include <linux/of.h>
+#include <linux/perf_event.h>
+#include <linux/platform_device.h>
+#include <linux/smp.h>
+
+#define NUM_COUNTERS		4
+#define TIMER_PERIOD		1000000000u
+#define to_k3_ddr_pmu(p)	container_of(p, struct k3_ddr_pmu, pmu)
+
+/* Maximum event config value from the hardware event table */
+#define K3_DDR_PMU_MAX_EVENT	0x23
+
+#define DDR_PERF_DEV_NAME	"k3_ddr"
+#define DDR_CPUHP_CB_NAME	DDR_PERF_DEV_NAME "_perf_pmu"
+
+static DEFINE_IDA(k3_ddr_ida);
+
+/**
+ * struct k3_ddr_pmu - a struct containing all information needed by pmu driver
+ * @pmu: pmu instance
+ * @cntrl_base: base address of the control register for the counters
+ * @counter_base: base address of the first counter
+ * @cpu: cpu to which pmu is attached to
+ * @dev: reference to the struct device
+ * @events: array of perf events registered by the driver
+ * @active_events: number of active perf events
+ * @cpuhp_state: cpu hotplug state
+ * @node: node for the cpu hotplug state
+ * @identifier: SoC identifier string for /sys/.../identifier
+ * @hrtimer: hrtimer for sampling events accurately
+ * @id: driver id
+ *
+ * PMU driver related information
+ */
+struct k3_ddr_pmu {
+	struct pmu pmu;
+	void __iomem *cntrl_base;
+	void __iomem *counter_base;
+	unsigned int cpu;
+	struct device *dev;
+	struct perf_event *events[NUM_COUNTERS];
+	unsigned int active_events;
+	enum cpuhp_state cpuhp_state;
+	struct hlist_node node;
+	const char *identifier;
+	struct hrtimer hrtimer;
+	int id;
+};
+
+static ssize_t k3_ddr_perf_identifier_show(struct device *dev,
+					   struct device_attribute *attr,
+					    char *page)
+{
+	struct k3_ddr_pmu *pmu = dev_get_drvdata(dev);
+
+	if (!pmu || !pmu->identifier)
+		return 0;
+
+	return sysfs_emit(page, "%s\n", pmu->identifier);
+}
+
+static umode_t k3_ddr_perf_identifier_attr_visible(struct kobject *kobj,
+						   struct attribute *attr,
+						    int n)
+{
+	struct device *dev = kobj_to_dev(kobj);
+	struct k3_ddr_pmu *pmu = dev_get_drvdata(dev);
+
+	if (!pmu->identifier)
+		return 0;
+
+	return attr->mode;
+}
+
+static struct device_attribute k3_ddr_perf_identifier_attr =
+	__ATTR(identifier, 0444, k3_ddr_perf_identifier_show, NULL);
+
+static struct attribute *k3_ddr_perf_identifier_attrs[] = {
+	&k3_ddr_perf_identifier_attr.attr,
+	NULL,
+};
+
+static const struct attribute_group k3_ddr_perf_identifier_attr_group = {
+	.attrs = k3_ddr_perf_identifier_attrs,
+	.is_visible = k3_ddr_perf_identifier_attr_visible,
+};
+
+static ssize_t k3_ddr_perf_cpumask_show(struct device *dev,
+					struct device_attribute *attr,
+					 char *buf)
+{
+	struct k3_ddr_pmu *pmu = dev_get_drvdata(dev);
+
+	return sysfs_emit(buf, "%*pbl\n", cpumask_pr_args(cpumask_of(pmu->cpu)));
+}
+
+static struct device_attribute k3_ddr_perf_cpumask_attr =
+	__ATTR(cpumask, 0444, k3_ddr_perf_cpumask_show, NULL);
+
+static struct attribute *k3_ddr_perf_cpumask_attrs[] = {
+	&k3_ddr_perf_cpumask_attr.attr,
+	NULL,
+};
+
+static const struct attribute_group k3_ddr_perf_cpumask_attr_group = {
+	.attrs = k3_ddr_perf_cpumask_attrs,
+};
+
+static ssize_t
+k3_ddr_pmu_event_show(struct device *dev, struct device_attribute *attr,
+		      char *page)
+{
+	struct perf_pmu_events_attr *pmu_attr;
+
+	pmu_attr = container_of(attr, struct perf_pmu_events_attr, attr);
+
+	return sysfs_emit(page, "event=0x%02llx\n", pmu_attr->id);
+}
+
+#define K3_DDR_PMU_EVENT_ATTR(_name, _id)		\
+	PMU_EVENT_ATTR_ID(_name, k3_ddr_pmu_event_show, _id)
+
+static struct attribute *k3_ddr_perf_events_attrs[] = {
+	K3_DDR_PMU_EVENT_ATTR(write, 0x00),
+	K3_DDR_PMU_EVENT_ATTR(read, 0x01),
+	K3_DDR_PMU_EVENT_ATTR(read_rmw, 0x02),
+	K3_DDR_PMU_EVENT_ATTR(activate, 0x03),
+	K3_DDR_PMU_EVENT_ATTR(precharge, 0x04),
+	K3_DDR_PMU_EVENT_ATTR(precharge_all, 0x05),
+	K3_DDR_PMU_EVENT_ATTR(mode_reg_read, 0x06),
+	K3_DDR_PMU_EVENT_ATTR(mode_reg_write, 0x07),
+	K3_DDR_PMU_EVENT_ATTR(per_bank_refresh, 0x08),
+	K3_DDR_PMU_EVENT_ATTR(auto_refresh, 0x09),
+	K3_DDR_PMU_EVENT_ATTR(zq_calib_long, 0x0a),
+	K3_DDR_PMU_EVENT_ATTR(zq_calib_short, 0x0b),
+	K3_DDR_PMU_EVENT_ATTR(bus_turn_around, 0x0c),
+	K3_DDR_PMU_EVENT_ATTR(write_write_collision, 0x0d),
+	K3_DDR_PMU_EVENT_ATTR(write_read_collision, 0x0e),
+	K3_DDR_PMU_EVENT_ATTR(read_write_collision, 0x0f),
+	K3_DDR_PMU_EVENT_ATTR(read_read_collision, 0x10),
+	K3_DDR_PMU_EVENT_ATTR(exit_power_down_self_refresh, 0x11),
+	K3_DDR_PMU_EVENT_ATTR(entry_power_down_self_refresh, 0x12),
+	K3_DDR_PMU_EVENT_ATTR(power_down_self_refresh_cycles, 0x13),
+	K3_DDR_PMU_EVENT_ATTR(exit_power_down, 0x14),
+	K3_DDR_PMU_EVENT_ATTR(entry_power_down, 0x15),
+	K3_DDR_PMU_EVENT_ATTR(power_down_cycles, 0x16),
+	K3_DDR_PMU_EVENT_ATTR(exit_self_refresh, 0x17),
+	K3_DDR_PMU_EVENT_ATTR(entry_self_refresh, 0x18),
+	K3_DDR_PMU_EVENT_ATTR(self_refresh_cycles, 0x19),
+	/* 0x1a and 0x1b are reserved in the hardware event table */
+	K3_DDR_PMU_EVENT_ATTR(command_queue_full_cycles, 0x1c),
+	K3_DDR_PMU_EVENT_ATTR(info_fifo_full_cycles, 0x1d),
+	K3_DDR_PMU_EVENT_ATTR(write_latency_fifo_full_cycles, 0x1e),
+	K3_DDR_PMU_EVENT_ATTR(port_command_fifo_full_cycles, 0x1f),
+	K3_DDR_PMU_EVENT_ATTR(write_response_fifo_full_cycles, 0x20),
+	K3_DDR_PMU_EVENT_ATTR(port_write_fifo_full_cycles, 0x21),
+	K3_DDR_PMU_EVENT_ATTR(core_read_fifo_full_cycles, 0x22),
+	K3_DDR_PMU_EVENT_ATTR(port_read_fifo_full_cycles, 0x23),
+	NULL,
+};
+
+static const struct attribute_group k3_ddr_perf_events_attr_group = {
+	.name = "events",
+	.attrs = k3_ddr_perf_events_attrs,
+};
+
+PMU_FORMAT_ATTR(event, "config:0-5");
+
+static struct attribute *k3_ddr_perf_format_attrs[] = {
+	&format_attr_event.attr,
+	NULL,
+};
+
+static const struct attribute_group k3_ddr_perf_format_attr_group = {
+	.name = "format",
+	.attrs = k3_ddr_perf_format_attrs,
+};
+
+static const struct attribute_group *attr_groups[] = {
+	&k3_ddr_perf_events_attr_group,
+	&k3_ddr_perf_format_attr_group,
+	&k3_ddr_perf_cpumask_attr_group,
+	&k3_ddr_perf_identifier_attr_group,
+	NULL,
+};
+
+static int k3_ddr_perf_alloc_counter(struct k3_ddr_pmu *pmu)
+{
+	for (int i = 0; i < NUM_COUNTERS; i++) {
+		if (!pmu->events[i]) {
+			pmu->active_events++;
+			return i;
+		}
+	}
+
+	return -ENOENT;
+}
+
+static void k3_ddr_perf_free_counter(struct k3_ddr_pmu *pmu, int counter)
+{
+	pmu->active_events--;
+	pmu->events[counter] = NULL;
+}
+
+static u32 k3_ddr_perf_read_counter(struct k3_ddr_pmu *pmu, int counter)
+{
+	void __iomem *base = pmu->counter_base;
+
+	return readl_relaxed(base + counter * 4);
+}
+
+static int k3_ddr_perf_event_init(struct perf_event *event)
+{
+	struct k3_ddr_pmu *pmu = to_k3_ddr_pmu(event->pmu);
+	struct hw_perf_event *hwc = &event->hw;
+
+	if (event->attr.type != event->pmu->type)
+		return -ENOENT;
+
+	if (event->attr.config > K3_DDR_PMU_MAX_EVENT)
+		return -EINVAL;
+
+	if (is_sampling_event(event) || event->attach_state & PERF_ATTACH_TASK)
+		return -EOPNOTSUPP;
+
+	if (event->cpu < 0)
+		return -EOPNOTSUPP;
+
+	if (event->group_leader->pmu != event->pmu &&
+	    !is_software_event(event->group_leader))
+		return -EINVAL;
+
+	event->cpu = pmu->cpu;
+	hwc->idx = -1;
+
+	return 0;
+}
+
+static void k3_ddr_perf_counter_enable(struct k3_ddr_pmu *pmu, int config,
+				       int counter, bool enable)
+{
+	u32 val;
+	u8 pos = counter * 8;
+
+	/*
+	 * Each CNT_SEL field is 6 bits wide with 2 reserved bits above it.
+	 * Bit layout: CNT1[5:0], rsvd[7:6], CNT2[13:8], rsvd[15:14], ...
+	 * There is no hardware enable/disable - writing config=0 counts writes.
+	 */
+	val = readl_relaxed(pmu->cntrl_base);
+	val &= ~(0x3FU << pos);
+	if (enable)
+		val |= ((u32)(config & 0x3F)) << pos;
+	writel_relaxed(val, pmu->cntrl_base);
+}
+
+static void k3_ddr_perf_event_update(struct perf_event *event)
+{
+	struct k3_ddr_pmu *pmu = to_k3_ddr_pmu(event->pmu);
+	struct hw_perf_event *hwc = &event->hw;
+	u64 new_raw_count, old_raw_count, actual_count;
+	int counter = hwc->idx;
+
+	do {
+		old_raw_count = local64_read(&hwc->prev_count);
+		new_raw_count = k3_ddr_perf_read_counter(pmu, counter);
+	} while (local64_cmpxchg(&hwc->prev_count, old_raw_count,
+				 new_raw_count) != old_raw_count);
+
+	actual_count = (new_raw_count - old_raw_count) & 0xffffffff;
+
+	local64_add(actual_count, &event->count);
+}
+
+static void k3_ddr_perf_event_start(struct perf_event *event, int flags)
+{
+	struct k3_ddr_pmu *pmu = to_k3_ddr_pmu(event->pmu);
+	struct hw_perf_event *hwc = &event->hw;
+	int counter = hwc->idx;
+	u64 initial_raw_count;
+
+	k3_ddr_perf_counter_enable(pmu, event->attr.config, counter, true);
+	initial_raw_count = k3_ddr_perf_read_counter(pmu, counter);
+	local64_set(&hwc->prev_count, initial_raw_count);
+
+	/* Only arm the timer when the first event becomes active */
+	if (pmu->active_events == 1)
+		hrtimer_start(&pmu->hrtimer, ns_to_ktime(TIMER_PERIOD),
+			      HRTIMER_MODE_REL_PINNED);
+
+	hwc->state = 0;
+}
+
+static int k3_ddr_perf_event_add(struct perf_event *event, int flags)
+{
+	struct k3_ddr_pmu *pmu = to_k3_ddr_pmu(event->pmu);
+	struct hw_perf_event *hwc = &event->hw;
+	int counter;
+
+	counter = k3_ddr_perf_alloc_counter(pmu);
+	if (counter < 0) {
+		dev_dbg(pmu->dev, "There are not enough counters\n");
+		return -EOPNOTSUPP;
+	}
+
+	pmu->events[counter] = event;
+
+	hwc->idx = counter;
+	local64_set(&hwc->prev_count, k3_ddr_perf_read_counter(pmu, counter));
+	hwc->state |= PERF_HES_STOPPED;
+
+	if (flags & PERF_EF_START)
+		k3_ddr_perf_event_start(event, flags);
+
+	return 0;
+}
+
+static void k3_ddr_perf_event_stop(struct perf_event *event, int flags)
+{
+	struct k3_ddr_pmu *pmu = to_k3_ddr_pmu(event->pmu);
+	struct hw_perf_event *hwc = &event->hw;
+	int counter = hwc->idx;
+
+	k3_ddr_perf_counter_enable(pmu, event->attr.config, counter, false);
+	k3_ddr_perf_event_update(event);
+
+	hwc->state |= PERF_HES_STOPPED;
+}
+
+static void k3_ddr_perf_event_del(struct perf_event *event, int flags)
+{
+	struct k3_ddr_pmu *pmu = to_k3_ddr_pmu(event->pmu);
+	struct hw_perf_event *hwc = &event->hw;
+	int counter = hwc->idx;
+
+	k3_ddr_perf_event_stop(event, PERF_EF_UPDATE);
+
+	k3_ddr_perf_free_counter(pmu, counter);
+
+	if (!pmu->active_events)
+		hrtimer_cancel(&pmu->hrtimer);
+
+	hwc->idx = -1;
+}
+
+static void k3_ddr_perf_overflow_handler(struct k3_ddr_pmu *pmu)
+{
+	for (int i = 0; i < NUM_COUNTERS; i++) {
+		struct perf_event *event = pmu->events[i];
+
+		if (event)
+			k3_ddr_perf_event_update(event);
+	}
+}
+
+static enum hrtimer_restart k3_ddr_perf_timer_handler(struct hrtimer *hrtimer)
+{
+	struct k3_ddr_pmu *pmu = container_of(hrtimer, struct k3_ddr_pmu, hrtimer);
+
+	k3_ddr_perf_overflow_handler(pmu);
+	hrtimer_forward_now(hrtimer, ns_to_ktime(TIMER_PERIOD));
+
+	return HRTIMER_RESTART;
+}
+
+static int k3_ddr_perf_init(struct k3_ddr_pmu *pmu, void __iomem *base,
+			    struct device *dev)
+{
+	*pmu = (struct k3_ddr_pmu) {
+		.pmu = (struct pmu) {
+			.module		 = THIS_MODULE,
+			.capabilities	 = PERF_PMU_CAP_NO_EXCLUDE,
+			.task_ctx_nr	 = perf_invalid_context,
+			.attr_groups	 = attr_groups,
+			.event_init	 = k3_ddr_perf_event_init,
+			.add		 = k3_ddr_perf_event_add,
+			.del		 = k3_ddr_perf_event_del,
+			.start		 = k3_ddr_perf_event_start,
+			.stop		 = k3_ddr_perf_event_stop,
+			.read		 = k3_ddr_perf_event_update,
+		},
+		.cntrl_base = base,
+		.counter_base = base + 4,
+		.dev = dev,
+	};
+
+	pmu->id = ida_alloc(&k3_ddr_ida, GFP_KERNEL);
+	return pmu->id;
+}
+
+static int k3_ddr_perf_offline_cpu(unsigned int cpu, struct hlist_node *node)
+{
+	struct k3_ddr_pmu *pmu = hlist_entry_safe(node, struct k3_ddr_pmu, node);
+	int target;
+
+	if (cpu != pmu->cpu)
+		return 0;
+
+	target = cpumask_any_but(cpu_online_mask, cpu);
+	if (target >= nr_cpu_ids)
+		return 0;
+
+	perf_pmu_migrate_context(&pmu->pmu, cpu, target);
+	pmu->cpu = target;
+
+	return 0;
+}
+
+static int k3_ddr_perf_probe(struct platform_device *pdev)
+{
+	struct device *dev = &pdev->dev;
+	struct ti_ddrss_dev *parent_dev = dev_get_drvdata(dev->parent);
+	u32 pmu_offset = 0x100;
+	struct k3_ddr_pmu *pmu;
+	void __iomem *base;
+	char *name;
+	int num;
+	int ret;
+
+	if (!parent_dev)
+		return dev_err_probe(dev, -ENODEV, "Parent DDR subsystem not found\n");
+
+	if (!parent_dev->sscfg)
+		return dev_err_probe(dev, -EINVAL, "Parent SSCFG not mapped\n");
+
+	/*
+	 * PMU registers are in SSCFG space. The pmu DT node uses 2-cell
+	 * addressing (#address-cells = 2), so cell index 1 is the low word
+	 * of the 64-bit address, which is the byte offset within SSCFG.
+	 */
+	of_property_read_u32_index(dev->of_node, "reg", 1, &pmu_offset);
+	base = parent_dev->sscfg + pmu_offset;
+
+	pmu = devm_kzalloc(dev, sizeof(*pmu), GFP_KERNEL);
+	if (!pmu)
+		return -ENOMEM;
+
+	num = k3_ddr_perf_init(pmu, base, dev);
+	if (num < 0)
+		return dev_err_probe(dev, num, "Failed to allocate PMU id\n");
+
+	name = devm_kasprintf(dev, GFP_KERNEL, DDR_PERF_DEV_NAME "%d", num);
+	if (!name) {
+		ret = -ENOMEM;
+		goto cpuhp_state_err;
+	}
+
+	pmu->identifier = parent_dev->cfg->identifier;
+	platform_set_drvdata(pdev, pmu);
+
+	hrtimer_setup(&pmu->hrtimer, k3_ddr_perf_timer_handler, CLOCK_MONOTONIC,
+		      HRTIMER_MODE_REL);
+
+	pmu->cpu = raw_smp_processor_id();
+	ret = cpuhp_setup_state_multi(CPUHP_AP_ONLINE_DYN,
+				      DDR_CPUHP_CB_NAME,
+				      NULL,
+				      k3_ddr_perf_offline_cpu);
+	if (ret < 0) {
+		dev_err(dev, "cpuhp_setup_state_multi failed: %d\n", ret);
+		goto cpuhp_state_err;
+	}
+
+	pmu->cpuhp_state = ret;
+
+	ret = cpuhp_state_add_instance_nocalls(pmu->cpuhp_state, &pmu->node);
+	if (ret)
+		goto cpuhp_instance_err;
+
+	ret = perf_pmu_register(&pmu->pmu, name, -1);
+	if (ret)
+		goto k3_ddr_perf_err;
+
+	return 0;
+
+k3_ddr_perf_err:
+	cpuhp_state_remove_instance_nocalls(pmu->cpuhp_state, &pmu->node);
+cpuhp_instance_err:
+	cpuhp_remove_multi_state(pmu->cpuhp_state);
+cpuhp_state_err:
+	ida_free(&k3_ddr_ida, pmu->id);
+
+	return ret;
+}
+
+static void k3_ddr_perf_remove(struct platform_device *pdev)
+{
+	struct k3_ddr_pmu *pmu = platform_get_drvdata(pdev);
+
+	perf_pmu_unregister(&pmu->pmu);
+
+	cpuhp_state_remove_instance_nocalls(pmu->cpuhp_state, &pmu->node);
+	cpuhp_remove_multi_state(pmu->cpuhp_state);
+
+	hrtimer_cancel(&pmu->hrtimer);
+
+	ida_free(&k3_ddr_ida, pmu->id);
+}
+
+static const struct of_device_id ti_k3_ddr_pmu_of_match[] = {
+	{ .compatible = "ti,k3-ddr-pmu" },
+	{}
+};
+MODULE_DEVICE_TABLE(of, ti_k3_ddr_pmu_of_match);
+
+static struct platform_driver ti_k3_ddr_pmu_driver = {
+	.driver = {
+		.name = "ti-k3-ddr-pmu",
+		.of_match_table = ti_k3_ddr_pmu_of_match,
+		.suppress_bind_attrs = true,
+	},
+	.probe = k3_ddr_perf_probe,
+	.remove = k3_ddr_perf_remove,
+};
+module_platform_driver(ti_k3_ddr_pmu_driver);
+
+MODULE_DESCRIPTION("PMU driver for TI K3 DDR Controller");
+MODULE_AUTHOR("Texas Instruments Inc");
+MODULE_LICENSE("GPL");
-- 
2.34.1

From: Santhosh Kumar K <s-k6@ti.com>

Add a driver to monitor LPDDR4 temperature via the MR4 register
and adjust DDR refresh timing (tRAS_MAX, tREF) in the kernel on
every TUF interrupt following JEDEC recommendations. Exposes
refresh_status (RO) and auto_adjust (RW) sysfs attributes.

Signed-off-by: Santhosh Kumar K <s-k6@ti.com>
Signed-off-by: Gandhar Deshpande <g-deshpande@ti.com>
Signed-off-by: Neha Malcom Francis <n-francis@ti.com>
Signed-off-by: MANNURU VENKATESWARLU <v-mannuru@ti.com>
---
 drivers/memory/Kconfig        |  19 ++
 drivers/memory/Makefile       |   1 +
 drivers/memory/ti-ddrss-mr4.c | 322 ++++++++++++++++++++++++++++++++++
 3 files changed, 342 insertions(+)
 create mode 100644 drivers/memory/ti-ddrss-mr4.c

diff --git a/drivers/memory/Kconfig b/drivers/memory/Kconfig
index e5527020ff337..259654a12650a 100644
--- a/drivers/memory/Kconfig
+++ b/drivers/memory/Kconfig
@@ -231,6 +231,25 @@ config STM32_OMM
 	    - chip select selection override.
 	    - the time between 2 transactions in multiplexed mode.
 
+config K3_DDR_MR4
+	tristate "Texas Instruments K3 DDR MR4 refresh rate driver"
+	depends on ARCH_K3 || COMPILE_TEST
+	depends on MFD_TI_DDRSS
+	help
+	  Say Y here to enable automatic DDR refresh rate adjustment for TI K3
+	  SoCs (AM62x, AM62Ax, AM62Px, AM64x, J721E, J7200, J721S2, J784S4).
+
+	  On every TUF interrupt the driver reads the MR4 temperature sensor,
+	  takes the maximum across all channels, and updates tRAS_MAX and tREF
+	  for all three Frequency Set Points.  The auto_adjust sysfs attribute
+	  allows userspace to disable kernel adjustment and observe the MR4
+	  state via refresh_status.
+
+	  This extends the LPDDR MR4 derating pattern from drivers/memory/emif.c
+	  (LPDDR2) to LPDDR4 on Cadence controllers.
+
+	  To compile as a module: the module will be called ti-ddrss-mr4.
+
 source "drivers/memory/samsung/Kconfig"
 source "drivers/memory/tegra/Kconfig"
 
diff --git a/drivers/memory/Makefile b/drivers/memory/Makefile
index 3ee883c8759a9..18556ba8bb2a9 100644
--- a/drivers/memory/Makefile
+++ b/drivers/memory/Makefile
@@ -29,6 +29,7 @@ obj-$(CONFIG_SAMSUNG_MC)	+= samsung/
 obj-$(CONFIG_TEGRA_MC)		+= tegra/
 obj-$(CONFIG_TI_EMIF_SRAM)	+= ti-emif-sram.o
 obj-$(CONFIG_FPGA_DFL_EMIF)	+= dfl-emif.o
+obj-$(CONFIG_K3_DDR_MR4)	+= ti-ddrss-mr4.o
 
 ti-emif-sram-objs		:= ti-emif-pm.o ti-emif-sram-pm.o
 
diff --git a/drivers/memory/ti-ddrss-mr4.c b/drivers/memory/ti-ddrss-mr4.c
new file mode 100644
index 0000000000000..e37b791694987
--- /dev/null
+++ b/drivers/memory/ti-ddrss-mr4.c
@@ -0,0 +1,322 @@
+// SPDX-License-Identifier: GPL-2.0-only
+/*
+ * ti-ddrss-mr4.c -- TI K3 DDR MR4 temperature-driven refresh rate driver
+ *
+ * Copyright (C) 2026 Texas Instruments Incorporated - https://ti.com
+ */
+
+#include <linux/devm-helpers.h>
+#include <linux/interrupt.h>
+#include <linux/kstrtox.h>
+#include <linux/mfd/ti-ddrss.h>
+#include <linux/mod_devicetable.h>
+#include <linux/module.h>
+#include <linux/platform_device.h>
+#include <linux/regmap.h>
+#include <linux/sysfs.h>
+#include <linux/workqueue.h>
+
+#define K3_DDR_NUM_FSP        3
+
+/*
+ * MR4 OP[2:0] -> left-shift mapping (JEDEC).
+ * Boot programs base = 0.25x interval.  Shifting left relaxes
+ * the interval; shifting right tightens it toward the boot-safe value.
+ */
+static const u8 k3_ddr_mr4_shift[8] = {
+	[0] = 2,    /* cold:     1x nominal  */
+	[1] = 2,    /* cold:     1x nominal  */
+	[2] = 2,    /* cool:     1x nominal  */
+	[3] = 2,    /* normal:   1x nominal  */
+	[4] = 1,    /* warm:     0.5x        */
+	[5] = 0,    /* hot:      0.25x (boot)*/
+	[6] = 0,    /* very hot: 0.25x (boot)*/
+	[7] = 0,    /* critical: 0.25x (JEDEC high-temp limit exceeded ) */
+};
+
+static const char * const k3_ddr_mr4_status[] = {
+	[0] = "low temperature",
+	[1] = "4x refresh interval",
+	[2] = "2x refresh interval",
+	[3] = "1x refresh interval",
+	[4] = "0.5x refresh interval",
+	[5] = "0.25x refresh interval",
+	[6] = "0.25x refresh interval with derating",
+	[7] = "high temperature",
+};
+
+/**
+ * struct k3_ddr_mr4 - per-instance private data
+ * @fields:      regmap_field pointers for all register fields
+ * @dev:         device pointer
+ * @mr4_cached:  last MR4 reading, updated by the IRQ thread
+ * @auto_adjust: when true, IRQ thread writes tRAS_MAX/tREF on every TUF
+ * @tras_nom:    boot-time tRAS_MAX base values for FSP 0, 1, 2
+ * @tref_nom:    boot-time tREF base values for FSP 0, 1, 2
+ * @cfg:         SoC-specific register configuration from the MFD parent
+ * @notify_work: deferred work to push sysfs uevent after each TUF
+ */
+struct k3_ddr_mr4 {
+	struct regmap_field		*fields[K3_DDR_MAX_FIELDS];
+	struct device			*dev;
+	u8				mr4_cached;
+	bool				auto_adjust;
+	u32				tras_nom[K3_DDR_NUM_FSP];
+	u32				tref_nom[K3_DDR_NUM_FSP];
+	const struct k3_ddr_cfg		*cfg;
+	struct work_struct		notify_work;
+};
+
+static ssize_t refresh_status_show(struct device *dev,
+				   struct device_attribute *attr,
+				   char *buf)
+{
+	struct k3_ddr_mr4 *priv = dev_get_drvdata(dev);
+	u8 mr4 = READ_ONCE(priv->mr4_cached);
+
+	if (mr4 >= ARRAY_SIZE(k3_ddr_mr4_status))
+		return sysfs_emit(buf, "unknown\n");
+
+	return sysfs_emit(buf, "%s\n", k3_ddr_mr4_status[mr4]);
+}
+static DEVICE_ATTR_RO(refresh_status);
+
+static ssize_t auto_adjust_show(struct device *dev,
+				struct device_attribute *attr,
+				char *buf)
+{
+	struct k3_ddr_mr4 *priv = dev_get_drvdata(dev);
+
+	return sysfs_emit(buf, "%u\n", READ_ONCE(priv->auto_adjust) ? 1 : 0);
+}
+
+static ssize_t auto_adjust_store(struct device *dev,
+				 struct device_attribute *attr,
+				 const char *buf, size_t count)
+{
+	struct k3_ddr_mr4 *priv = dev_get_drvdata(dev);
+	bool val;
+	int ret;
+
+	ret = kstrtobool(buf, &val);
+	if (ret)
+		return ret;
+
+	WRITE_ONCE(priv->auto_adjust, val);
+	return count;
+}
+static DEVICE_ATTR_RW(auto_adjust);
+
+static struct attribute *k3_ddr_mr4_attrs[] = {
+	&dev_attr_refresh_status.attr,
+	&dev_attr_auto_adjust.attr,
+	NULL,
+};
+ATTRIBUTE_GROUPS(k3_ddr_mr4);
+
+static void k3_ddr_mr4_notify_work(struct work_struct *work)
+{
+	struct k3_ddr_mr4 *priv =
+		container_of(work, struct k3_ddr_mr4, notify_work);
+
+	sysfs_notify(&priv->dev->kobj, NULL, "refresh_status");
+	kobject_uevent(&priv->dev->kobj, KOBJ_CHANGE);
+}
+
+static irqreturn_t k3_ddr_mr4_irq_thread(int irq, void *data)
+{
+	struct k3_ddr_mr4 *priv = data;
+	unsigned int reg0_fld0, reg0_fld1, reg1_fld0, reg1_fld1;
+	unsigned int stat_group = 0, stat_tuf = 0;
+	u8 temp0, temp1, max_mr4;
+	int i;
+
+	/* AM62/AM62A: check group interrupt status before anything else */
+	if (priv->cfg->has_intr_group) {
+		if (regmap_field_read(priv->fields[K3_DDR_INT_STAT_MASTER],
+				      &stat_group))
+			return IRQ_NONE;
+		if (!stat_group)
+			return IRQ_NONE;
+	}
+
+	/* Verify TUF is the source before reading MR4 */
+	if (regmap_field_read(priv->fields[K3_DDR_INT_STAT_TUF], &stat_tuf))
+		return IRQ_NONE;
+	if (!stat_tuf)
+		return IRQ_NONE;
+
+	if (regmap_field_read(priv->fields[K3_DDR_TEMP_REG0_FIELD0],
+			      &reg0_fld0) ||
+	    regmap_field_read(priv->fields[K3_DDR_TEMP_REG0_FIELD1],
+			      &reg0_fld1) ||
+	    regmap_field_read(priv->fields[K3_DDR_TEMP_REG1_FIELD0],
+			      &reg1_fld0) ||
+	    regmap_field_read(priv->fields[K3_DDR_TEMP_REG1_FIELD1],
+			      &reg1_fld1))
+		return IRQ_NONE;
+
+	temp0 = max(reg0_fld0, reg0_fld1);
+	temp1 = max(reg1_fld0, reg1_fld1);
+	max_mr4 = max(temp0, temp1);
+
+	WRITE_ONCE(priv->mr4_cached, max_mr4);
+
+	dev_dbg(priv->dev, "TUF: MR4=%u (%s)\n", max_mr4,
+		max_mr4 < ARRAY_SIZE(k3_ddr_mr4_status) ?
+		k3_ddr_mr4_status[max_mr4] : "unknown");
+
+/* ACK unconditionally - even when auto_adjust is off - to prevent IRQ storm. */
+	regmap_field_write(priv->fields[K3_DDR_INT_ACK_TUF], 1);
+
+	schedule_work(&priv->notify_work);
+
+	if (!READ_ONCE(priv->auto_adjust))
+		return IRQ_HANDLED;
+
+	for (i = 0; i < K3_DDR_NUM_FSP; i++) {
+		regmap_field_write(priv->fields[K3_DDR_TRAS_MAX_F0 + i],
+				   priv->tras_nom[i] <<
+				   k3_ddr_mr4_shift[max_mr4]);
+		regmap_field_write(priv->fields[K3_DDR_TREF_F0 + i],
+				   priv->tref_nom[i] <<
+				   k3_ddr_mr4_shift[max_mr4]);
+	}
+
+	return IRQ_HANDLED;
+}
+
+static int k3_ddr_mr4_probe(struct platform_device *pdev)
+{
+	struct device *dev = &pdev->dev;
+	struct ti_ddrss_dev *ddrss;
+	struct k3_ddr_mr4 *priv;
+	unsigned int v;
+	int i, ret;
+
+	ddrss = dev_get_drvdata(dev->parent);
+	if (!ddrss)
+		return dev_err_probe(dev, -ENODEV,
+				     "Failed to get parent drvdata\n");
+
+	priv = devm_kzalloc(dev, sizeof(*priv), GFP_KERNEL);
+	if (!priv)
+		return -ENOMEM;
+
+	priv->dev = dev;
+	priv->cfg = ddrss->cfg;
+	priv->auto_adjust = true;
+
+	for (i = 0; i < K3_DDR_MAX_FIELDS; i++) {
+		priv->fields[i] = devm_regmap_field_alloc(dev, ddrss->regmap,
+							  ddrss->cfg->cfg_fields[i]);
+		if (IS_ERR(priv->fields[i]))
+			return dev_err_probe(dev, PTR_ERR(priv->fields[i]),
+					     "Failed to alloc regmap field %d\n",
+					     i);
+	}
+
+	/*
+	 * Save boot-time tRAS_MAX and tREF (boot programs 0.25x interval).
+	 * All run-time adjustments shift from these base values.
+	 */
+	for (i = 0; i < K3_DDR_NUM_FSP; i++) {
+		ret = regmap_field_read(priv->fields[K3_DDR_TRAS_MAX_F0 + i],
+					&v);
+		if (ret)
+			return dev_err_probe(dev, ret,
+					     "Failed to read tRAS_MAX FSP%d\n",
+					     i);
+		priv->tras_nom[i] = v;
+
+		ret = regmap_field_read(priv->fields[K3_DDR_TREF_F0 + i], &v);
+		if (ret)
+			return dev_err_probe(dev, ret,
+					     "Failed to read tREF FSP%d\n", i);
+		priv->tref_nom[i] = v;
+	}
+
+	/* Read initial MR4 so refresh_status is valid before first TUF. */
+	{
+		unsigned int r0f0, r0f1, r1f0, r1f1;
+		u8 t0, t1, init_mr4;
+
+		if (regmap_field_read(priv->fields[K3_DDR_TEMP_REG0_FIELD0],
+				      &r0f0) ||
+		    regmap_field_read(priv->fields[K3_DDR_TEMP_REG0_FIELD1],
+				      &r0f1) ||
+		    regmap_field_read(priv->fields[K3_DDR_TEMP_REG1_FIELD0],
+				      &r1f0) ||
+		    regmap_field_read(priv->fields[K3_DDR_TEMP_REG1_FIELD1],
+				      &r1f1)) {
+			init_mr4 = 3;
+		} else {
+			t0 = max(r0f0, r0f1);
+			t1 = max(r1f0, r1f1);
+			init_mr4 = max(t0, t1);
+			if (!init_mr4)
+				init_mr4 = 3; /* MR4=0 is invalid; fall back to nominal */
+		}
+		priv->mr4_cached = init_mr4;
+	}
+
+	ret = devm_work_autocancel(dev, &priv->notify_work,
+				   k3_ddr_mr4_notify_work);
+	if (ret)
+		return dev_err_probe(dev, ret, "Failed to init notify work\n");
+
+	ret = devm_request_threaded_irq(dev, ddrss->irq,
+					NULL, k3_ddr_mr4_irq_thread,
+					IRQF_ONESHOT | IRQF_NO_SUSPEND,
+					dev_name(dev), priv);
+	if (ret)
+		return dev_err_probe(dev, ret,
+				     "Failed to request threaded IRQ\n");
+
+	/*
+	 * Unmask after IRQ handler is registered to avoid losing early events.
+	 * J7: single bit.  AM62/AM62A: three levels (MISC group, global, TUF).
+	 */
+	ret = regmap_field_write(priv->fields[K3_DDR_INT_MASK_MASTER_MISC],
+				 0U);
+	if (ret)
+		return dev_err_probe(dev, ret, "Failed to unmask interrupt\n");
+
+	if (priv->cfg->has_mask_misc) {
+		ret = regmap_field_write(priv->fields[K3_DDR_INT_MASK_MASTER_GLOBAL],
+					 0U);
+		if (ret)
+			return dev_err_probe(dev, ret,
+					     "Failed to unmask global interrupt\n");
+
+		ret = regmap_field_write(priv->fields[K3_DDR_INT_MASK_TUF],
+					 0U);
+		if (ret)
+			return dev_err_probe(dev, ret,
+					     "Failed to unmask TUF interrupt\n");
+	}
+
+	platform_set_drvdata(pdev, priv);
+
+	return 0;
+}
+
+static const struct platform_device_id k3_ddr_mr4_id[] = {
+	{ "ti-ddrss-mr4", 0 },
+	{}
+};
+MODULE_DEVICE_TABLE(platform, k3_ddr_mr4_id);
+
+static struct platform_driver k3_ddr_mr4_driver = {
+	.driver = {
+		.name		= "ti-ddrss-mr4",
+		.dev_groups	= k3_ddr_mr4_groups,
+	},
+	.probe		= k3_ddr_mr4_probe,
+	.id_table	= k3_ddr_mr4_id,
+};
+module_platform_driver(k3_ddr_mr4_driver);
+
+MODULE_DESCRIPTION("TI K3 DDR MR4 temperature-driven refresh rate driver");
+MODULE_AUTHOR("Texas Instruments Inc");
+MODULE_LICENSE("GPL");
-- 
