+	.probe = mtk_disp_tdshp_probe,
+	.remove = mtk_disp_tdshp_remove,
+	.driver = {
+		.name = "mediatek-disp-tdshp",
+		.owner = THIS_MODULE,
+		.of_match_table = mtk_disp_tdshp_driver_dt_match,
+	},
